int lcs(int i, int j) {
    if (i == (int)t1.size() || j == (int)t2.size()) return 0;
    if (memo[i][j] != -1) return memo[i][j];
    if (t1[i] == t2[j]) return memo[i][j] = 1 + lcs(i+1, j+1);
    return memo[i][j] = max(lcs(i+1, j), lcs(i, j+1));
