import sys, json
heights = json.loads(sys.stdin.read().strip())
if not heights: print([]); exit()
rows, cols = len(heights), len(heights[0])
pac, atl = set(), set()
def dfs(r, c, visit, prev_h):
    if r<0 or r>=rows or c<0 or c>=cols or (r,c) in visit or heights[r][c]<prev_h: return
    visit.add((r,c))
    for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]: dfs(r+dr,c+dc,visit,heights[r][c])
for c in range(cols): dfs(0,c,pac,heights[0][c]); dfs(rows-1,c,atl,heights[rows-1][c])
for r in range(rows): dfs(r,0,pac,heights[r][0]); dfs(r,cols-1,atl,heights[r][cols-1])
result = sorted([list(x) for x in pac & atl])
print(json.dumps(result))

import sys, json
from collections import defaultdict, deque
words = json.loads(sys.stdin.read().strip())
adj = defaultdict(set)
in_deg = {c: 0 for w in words for c in w}
for i in range(len(words)-1):
    w1, w2 = words[i], words[i+1]
    minLen = min(len(w1), len(w2))
    if len(w1) > len(w2) and w1[:minLen] == w2[:minLen]: print(''); exit()
    for j in range(minLen):
        if w1[j] != w2[j]:
            if w2[j] not in adj[w1[j]]: adj[w1[j]].add(w2[j]); in_deg[w2[j]] += 1
            break
q = deque([c for c in in_deg if in_deg[c] == 0])
result = []
while q:
    c = q.popleft(); result.append(c)
    for nb in adj[c]:
        in_deg[nb] -= 1
        if in_deg[nb] == 0: q.append(nb)
print(''.join(result) if len(result) == len(in_deg) else '')

